import React, { useCallback, useState } from 'react';
import { SpeakerWaveIcon } from '@heroicons/react/24/solid';

interface AudioButtonProps {
  text: string;
  lang?: string; // Default 'zh-HK'
  label?: string;
  className?: string;
}

const AudioButton: React.FC<AudioButtonProps> = ({ 
  text, 
  lang = 'zh-HK', 
  label, 
  className = "" 
}) => {
  const [isSpeaking, setIsSpeaking] = useState(false);

  const speak = useCallback(() => {
    if (!window.speechSynthesis) {
      alert("您的瀏覽器不支持語音播放功能");
      return;
    }

    // Cancel any current speaking
    window.speechSynthesis.cancel();

    const utterance = new SpeechSynthesisUtterance(text);

    // Try to find a Cantonese voice
    const voices = window.speechSynthesis.getVoices();
    const cantoneseVoice = voices.find(v => 
      v.lang === 'zh-HK' || v.lang === 'zh-yue'
    );

    if (cantoneseVoice) {
      utterance.voice = cantoneseVoice;
    }

    utterance.lang = lang;
    utterance.rate = 0.8; // Slightly slower for learning

    utterance.onstart = () => setIsSpeaking(true);
    utterance.onend = () => setIsSpeaking(false);
    utterance.onerror = () => setIsSpeaking(false);

    window.speechSynthesis.speak(utterance);
  }, [text, lang]);

  return (
    <button
      onClick={speak}
      disabled={isSpeaking}
      className={`
        relative group overflow-hidden flex items-center gap-2 px-4 py-2 rounded-2xl transition-all transform active:scale-95
        ${isSpeaking 
          ? 'bg-crayon-green text-white shadow-inner' 
          : 'bg-crayon-yellow text-orange-900 shadow-[0_4px_0_rgb(202,138,4)] hover:shadow-[0_2px_0_rgb(202,138,4)] hover:translate-y-[2px]'
        } 
        ${className}
      `}
      title="播放讀音"
    >
      <SpeakerWaveIcon className={`w-6 h-6 ${isSpeaking ? 'animate-pulse' : ''}`} />
      {label && <span className="text-lg font-bold">{label}</span>}
    </button>
  );
};

export default AudioButton;

import React, { useEffect, useRef, useState } from 'react';

interface StrokeCharacterProps {
  char: string;
  size?: number;
  animate?: boolean;
  loop?: boolean;
  onLoad?: () => void;
}

const StrokeCharacter: React.FC<StrokeCharacterProps> = ({ 
  char, 
  size = 100, 
  animate = false,
  loop = false,
  onLoad
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const writerRef = useRef<any>(null);
  const isMounted = useRef(true);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(false);
  const loopRef = useRef(loop);
  const timeoutRef = useRef<number | null>(null);

  useEffect(() => {
    isMounted.current = true;
    return () => {
      isMounted.current = false;
      if (timeoutRef.current) {
        window.clearTimeout(timeoutRef.current);
      }
      if (writerRef.current) {
        try {
          writerRef.current.cancelQuiz();
          writerRef.current.hideCharacter();
        } catch (e) {
          // ignore cleanup errors
        }
      }
    };
  }, []);

  // Update loop ref
  useEffect(() => {
    loopRef.current = loop;
    // If loop is toggled on, and we aren't animating, we might want to restart
    if (loop && !isLoading && animate && writerRef.current) {
       // Logic to restart if idle can be complex, for now we rely on the next cycle
       // or the user manually triggering refresh
    }
  }, [loop, isLoading, animate]);

  const playAnimation = () => {
    if (!writerRef.current || !isMounted.current) return;

    if (timeoutRef.current) {
        window.clearTimeout(timeoutRef.current);
        timeoutRef.current = null;
    }

    // Get stroke count safely
    let strokeCount = 0;
    try {
        const character = writerRef.current.character;
        strokeCount = character && character.strokes ? character.strokes.length : 0;
    } catch (e) {
        console.warn("Error reading stroke count", e);
    }

    const COLOR_ACTIVE = '#fb7185'; // crayon-pink
    const COLOR_DEFAULT = '#334155'; // Slate-700

    // Reset visuals
    try {
        writerRef.current.cancelQuiz();
        writerRef.current.hideCharacter();
        writerRef.current.updateColor({ strokeColor: COLOR_DEFAULT });
    } catch (e) {
        console.warn("Error resetting writer", e);
    }

    if (strokeCount > 0) {
      let currentStroke = 0;

      const animateStep = () => {
        if (!isMounted.current) return;

        if (currentStroke >= strokeCount) {
          // Animation Complete
          if (writerRef.current) {
            try {
              writerRef.current.updateColor({ strokeColor: COLOR_DEFAULT });
              writerRef.current.showCharacter();
            } catch(e) {}
          }

          if (loopRef.current) {
            timeoutRef.current = window.setTimeout(playAnimation, 1000);
          }
          return;
        }

        if (writerRef.current) {
            try {
              writerRef.current.updateColor({
                strokeColor: (data: any) => {
                    return data.strokeNum === currentStroke ? COLOR_ACTIVE : COLOR_DEFAULT;
                }
              });

              writerRef.current.animateStroke(currentStroke, {
                onComplete: () => {
                    if (!isMounted.current) return;
                    currentStroke++;
                    animateStep();
                }
              });
            } catch (e) {
              console.warn("Animation step error", e);
            }
        }
      };

      animateStep();
    } else {
      // Fallback for missing data
      try {
        writerRef.current.animateCharacter({
          onComplete: () => {
            if (loopRef.current && isMounted.current) {
              timeoutRef.current = window.setTimeout(playAnimation, 1000);
            }
          }
        });
      } catch (e) {}
    }
  };

  useEffect(() => {
    if (!containerRef.current || !char) return;

    containerRef.current.innerHTML = '';
    setError(false);
    setIsLoading(true);
    writerRef.current = null;
    if (timeoutRef.current) clearTimeout(timeoutRef.current);

    const HanziWriter = window.HanziWriter;
    if (!HanziWriter) {
      console.error("HanziWriter not loaded");
      setError(true);
      return;
    }

    // Explicitly load data first to ensure we have stroke counts for custom animation
    HanziWriter.loadCharacterData(char)
      .then((charData: any) => {
        if (!isMounted.current) return;

        try {
          // Initialize Writer
          const writer = HanziWriter.create(containerRef.current, char, {
            width: size,
            height: size,
            padding: 5,
            showOutline: true,
            strokeAnimationSpeed: 1, 
            delayBetweenStrokes: 0, // Handled manually
            strokeColor: '#334155', 
            outlineColor: '#e2e8f0', // Lighter outline for cleaner look
            charDataLoader: () => charData // Use preloaded data
          });

          writerRef.current = writer;
          setIsLoading(false);
          if (onLoad) onLoad();

          // Trigger initial animation if needed
          if (animate) {
            timeoutRef.current = window.setTimeout(() => playAnimation(), 100);
          }
        } catch (err) {
          console.error("Error creating writer", err);
          setError(true);
          setIsLoading(false);
        }
      })
      .catch((err: any) => {
        if (!isMounted.current) return;
        console.error("Error loading character data", err);
        setError(true);
        setIsLoading(false);
      });

    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [char, size]); 

  // Watch for animate prop changes to re-trigger
  useEffect(() => {
    if (animate && !isLoading && writerRef.current) {
      playAnimation();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [animate, isLoading]);

  return (
    <div 
      className="relative bg-white rounded-2xl overflow-hidden border-2 border-slate-100 shadow-inner"
      style={{ width: size, height: size }}
    >
      {/* Grid lines background to look like exercise book */}
      <div className="absolute inset-0 pointer-events-none opacity-20" 
           style={{
             backgroundImage: 'linear-gradient(#cbd5e1 1px, transparent 1px), linear-gradient(90deg, #cbd5e1 1px, transparent 1px)',
             backgroundSize: '50% 50%'
           }}>
           <div className="w-full h-full border-2 border-dashed border-red-200/50 absolute top-0 left-0"></div>
           <div className="absolute top-1/2 left-0 w-full border-t border-red-200/50"></div>
           <div className="absolute left-1/2 top-0 h-full border-l border-red-200/50"></div>
      </div>

      <div ref={containerRef} className="w-full h-full flex items-center justify-center relative z-10" />

      {isLoading && (
        <div className="absolute inset-0 flex items-center justify-center bg-white/80 z-20">
           <svg className="animate-spin h-8 w-8 text-crayon-blue" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
             <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
             <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path>
           </svg>
        </div>
      )}

      {error && (
        <div className="absolute inset-0 flex items-center justify-center text-slate-300 text-5xl font-serif select-none z-20">
          {char}
        </div>
      )}
    </div>
  );
};

export default StrokeCharacter;

import React, { useState, useEffect, useRef } from 'react';
import { analyzeVocabList, generateWordImage } from './services/geminiService';
import StrokeCharacter from './components/StrokeCharacter';
import AudioButton from './components/AudioButton';
import { VocabGroup } from './types';
import { 
  PencilSquareIcon, 
  SparklesIcon, 
  ArrowPathIcon,
  PhotoIcon,
  ClockIcon,
  XMarkIcon,
  ArrowsRightLeftIcon,
  MagnifyingGlassPlusIcon,
  MagnifyingGlassMinusIcon,
  ExclamationCircleIcon,
  StarIcon,
  BookOpenIcon,
  FaceSmileIcon
} from '@heroicons/react/24/outline';

const HISTORY_KEY = 'cantonese_app_history';

const App: React.FC = () => {
  const [inputText, setInputText] = useState<string>('你好、學校、圖書館');

  const [vocabGroups, setVocabGroups] = useState<VocabGroup[]>([]);
  const [loading, setLoading] = useState<boolean>(false);

  // Selection State
  const [selectedGroupIndex, setSelectedGroupIndex] = useState<number>(0);

  // Animation State
  const [animateTrigger, setAnimateTrigger] = useState<boolean>(false);
  const [isLooping, setIsLooping] = useState<boolean>(false);

  // View Settings
  const [viewScale, setViewScale] = useState<number>(1.0);

  // History State
  const [history, setHistory] = useState<string[]>([]);

  // Initialize History
  useEffect(() => {
    const saved = localStorage.getItem(HISTORY_KEY);
    if (saved) {
      try {
        setHistory(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse history", e);
      }
    }

    // Initial analysis
    performAnalysis('你好、學校、圖書館', false);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const addToHistory = (text: string) => {
    setHistory(prev => {
      // Remove if exists to move to top, limit to 20 items
      const filtered = prev.filter(item => item !== text);
      const newHistory = [text, ...filtered].slice(0, 20);
      localStorage.setItem(HISTORY_KEY, JSON.stringify(newHistory));
      return newHistory;
    });
  };

  const removeFromHistory = (e: React.MouseEvent, textToRemove: string) => {
    e.stopPropagation();
    setHistory(prev => {
      const newHistory = prev.filter(item => item !== textToRemove);
      localStorage.setItem(HISTORY_KEY, JSON.stringify(newHistory));
      return newHistory;
    });
  };

  const adjustScale = (delta: number) => {
    setViewScale(prev => {
      const newVal = prev + delta;
      return Math.min(Math.max(newVal, 0.4), 2.0); // Expanded range
    });
  };

  // Effect to load image for the selected group if it doesn't exist
  useEffect(() => {
    const loadCurrentGroupImage = async () => {
      if (vocabGroups.length === 0) return;
      const group = vocabGroups[selectedGroupIndex];

      if (!group || group.imageUrl || group.isImageLoading || group.imageError) return;

      // Update state to loading
      setVocabGroups(prev => {
        const newGroups = [...prev];
        newGroups[selectedGroupIndex] = { ...newGroups[selectedGroupIndex], isImageLoading: true };
        return newGroups;
      });

      // Fetch image
      const result = await generateWordImage(group.text);

      // Update state with image
      setVocabGroups(prev => {
        const newGroups = [...prev];
        newGroups[selectedGroupIndex] = { 
          ...newGroups[selectedGroupIndex], 
          imageUrl: result.imageUrl,
          imageError: result.error,
          isImageLoading: false
        };
        return newGroups;
      });
    };

    loadCurrentGroupImage();
  }, [selectedGroupIndex, vocabGroups.length]); 

  const performAnalysis = async (text: string, saveHistory: boolean = true) => {
    if (!text.trim()) return;

    setLoading(true);
    setVocabGroups([]); 
    setSelectedGroupIndex(0);

    try {
      // Split by dunhao or standard commas
      const words = text.split(/[、,，]/).map(s => s.trim()).filter(s => s.length > 0);

      const analyzedGroups = await analyzeVocabList(words);
      setVocabGroups(analyzedGroups);

      if (saveHistory && analyzedGroups.length > 0) {
        addToHistory(text);
      }

    } catch (error) {
      console.error("Failed to analyze", error);
    } finally {
      setLoading(false);
    }
  };

  const handleAnalyzeClick = () => {
    performAnalysis(inputText, true);
  };

  const handleHistoryClick = (text: string) => {
    setInputText(text);
    performAnalysis(text, true); // Move to top of history
  };

  const triggerAnimation = () => {
    setAnimateTrigger(false);
    setTimeout(() => setAnimateTrigger(true), 50);
  };

  const handleGroupSelect = (index: number) => {
    setSelectedGroupIndex(index);
    setAnimateTrigger(false);
    setTimeout(() => setAnimateTrigger(true), 100);
  };

  const handleRandomSelect = () => {
    if (vocabGroups.length <= 1) return;
    let nextIndex = selectedGroupIndex;
    // Ensure we pick a different word if possible
    while (nextIndex === selectedGroupIndex) {
      nextIndex = Math.floor(Math.random() * vocabGroups.length);
    }
    handleGroupSelect(nextIndex);
  };

  const handleRegenerateImage = async (e: React.MouseEvent) => {
    e.stopPropagation();
    const group = vocabGroups[selectedGroupIndex];
    if (!group) return;

    // Set loading state
    setVocabGroups(prev => {
      const newGroups = [...prev];
      newGroups[selectedGroupIndex] = { ...group, isImageLoading: true, imageUrl: undefined, imageError: undefined };
      return newGroups;
    });

    // Fetch new image
    const result = await generateWordImage(group.text);

    // Update state
    setVocabGroups(prev => {
      const newGroups = [...prev];
      newGroups[selectedGroupIndex] = { 
        ...group, 
        isImageLoading: false, 
        imageUrl: result.imageUrl,
        imageError: result.error
      };
      return newGroups;
    });
  };

  const currentGroup = vocabGroups[selectedGroupIndex];

  return (
    <div className="min-h-screen bg-sky-100/50 flex flex-col font-sans text-slate-800 pb-12">

      {/* Fun Header */}
      <header className="bg-crayon-yellow border-b-4 border-yellow-500 sticky top-0 z-30 shadow-sm">
        <div className="max-w-6xl mx-auto px-4 py-3 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-white rounded-2xl shadow-sm rotate-3 border-2 border-yellow-600">
              <PencilSquareIcon className="w-7 h-7 text-yellow-600" />
            </div>
            <h1 className="text-2xl font-black tracking-tight text-yellow-900 drop-shadow-sm">
              粵語生字筆順王
            </h1>
          </div>
          <div className="hidden sm:flex items-center gap-2 bg-white/30 px-3 py-1.5 rounded-full border-2 border-white/40 text-yellow-900 text-xs font-bold">
             <SparklesIcon className="w-4 h-4" />
             AI 智能助教
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-6xl w-full mx-auto px-4 py-8 space-y-8">

        {/* Input Mission Control */}
        <section className="bg-white rounded-[2rem] p-6 shadow-[0_8px_0_rgb(0,0,0,0.05)] border-4 border-white ring-4 ring-sky-200">
          <label htmlFor="vocabInput" className="block text-lg font-bold text-sky-800 mb-3 flex items-center gap-2">
            <FaceSmileIcon className="w-6 h-6 text-sky-500" />
            輸入詞語（請用頓號、分開）：
          </label>
          <div className="flex flex-col sm:flex-row gap-3">
            <input
              id="vocabInput"
              type="text"
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleAnalyzeClick()}
              placeholder="例如：學校、圖書館、超級市場..."
              className="flex-1 border-2 border-sky-200 rounded-2xl px-5 py-4 text-lg focus:border-sky-400 focus:ring-4 focus:ring-sky-100 outline-none transition-all placeholder:text-sky-300"
            />
            <button
              onClick={handleAnalyzeClick}
              disabled={loading || !inputText.trim()}
              className="bg-crayon-blue hover:bg-sky-400 disabled:bg-slate-300 text-white px-8 py-4 rounded-2xl font-bold text-lg shadow-[0_4px_0_rgb(14,165,233)] hover:shadow-[0_2px_0_rgb(14,165,233)] hover:translate-y-[2px] active:translate-y-[4px] active:shadow-none transition-all flex items-center justify-center gap-2 whitespace-nowrap min-w-[140px]"
            >
              {loading ? (
                <ArrowPathIcon className="w-6 h-6 animate-spin" />
              ) : (
                <SparklesIcon className="w-6 h-6" />
              )}
              <span>開始！</span>
            </button>
          </div>

          {/* History Chips */}
          {history.length > 0 && (
            <div className="mt-6 pt-4 border-t-2 border-dashed border-slate-100">
              <div className="flex items-center gap-2 mb-3">
                <ClockIcon className="w-5 h-5 text-slate-400" />
                <h3 className="text-sm font-bold text-slate-400 uppercase tracking-wider">剛才學過</h3>
              </div>
              <div className="flex flex-wrap gap-2">
                {history.map(item => (
                  <div 
                    key={item} 
                    onClick={() => handleHistoryClick(item)}
                    className="group relative flex items-center gap-2 px-4 py-2 bg-slate-50 hover:bg-yellow-50 border-2 border-slate-200 hover:border-yellow-300 rounded-full cursor-pointer transition-all text-slate-600 hover:text-yellow-800"
                  >
                    <span className="font-medium">{item}</span>
                    <button 
                      onClick={(e) => removeFromHistory(e, item)}
                      className="p-1 rounded-full hover:bg-red-100 text-slate-300 hover:text-red-500 opacity-50 group-hover:opacity-100 transition-all"
                      title="刪除紀錄"
                    >
                      <XMarkIcon className="w-4 h-4" />
                    </button>
                  </div>
                ))}
              </div>
            </div>
          )}
        </section>

        {vocabGroups.length > 0 && currentGroup && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">

            {/* Main Display (Left Column) */}
            <div className="lg:col-span-8 flex flex-col gap-8">

              {/* Word Learning Card */}
              <div className="bg-white rounded-[2.5rem] p-6 sm:p-8 shadow-xl border-4 border-white ring-4 ring-purple-100 relative group/card overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-4 bg-purple-100"></div>

                {/* Zoom Controls */}
                <div className="absolute top-6 right-6 flex items-center gap-2 z-10">
                   <div className="flex bg-white/80 backdrop-blur border-2 border-slate-100 rounded-xl p-1 shadow-sm">
                      <button 
                        onClick={() => adjustScale(-0.1)}
                        className="p-1.5 text-slate-400 hover:bg-slate-100 rounded-lg hover:text-sky-500 transition-colors"
                        title="縮小"
                      >
                        <MagnifyingGlassMinusIcon className="w-5 h-5" />
                      </button>
                      <button 
                        onClick={() => adjustScale(0.1)}
                        className="p-1.5 text-slate-400 hover:bg-slate-100 rounded-lg hover:text-sky-500 transition-colors"
                        title="放大"
                      >
                        <MagnifyingGlassPlusIcon className="w-5 h-5" />
                      </button>
                   </div>
                </div>

                <div className="flex flex-col md:flex-row gap-8 mt-6 items-center md:items-start relative z-0">
                  {/* Image Section - Picture Frame Style */}
                  <div 
                    className="w-full aspect-square bg-slate-50 rounded-3xl flex items-center justify-center overflow-hidden border-4 border-slate-100 shadow-inner relative group flex-shrink-0 transition-all duration-300"
                    style={{ flexBasis: `${40 * viewScale}%`, maxWidth: '100%' }}
                  >
                    {currentGroup.isImageLoading ? (
                       <div className="flex flex-col items-center gap-3 text-crayon-blue">
                         <div className="relative">
                            <PhotoIcon className="w-16 h-16 animate-bounce opacity-50" />
                            <SparklesIcon className="w-8 h-8 absolute -top-2 -right-2 text-yellow-400 animate-spin" />
                         </div>
                         <span className="font-bold text-sm tracking-wide bg-sky-50 px-3 py-1 rounded-full">畫圖中...</span>
                       </div>
                    ) : currentGroup.imageUrl ? (
                      <>
                        <img 
                          src={currentGroup.imageUrl} 
                          alt={currentGroup.text} 
                          className="w-full h-full object-contain p-4 transition-transform duration-700 hover:scale-110" 
                        />
                        {/* Regenerate Button Overlay */}
                        <button
                          onClick={handleRegenerateImage}
                          className="absolute bottom-4 right-4 bg-white hover:bg-sky-50 text-slate-400 hover:text-sky-600 p-3 rounded-2xl shadow-lg border-2 border-slate-100 transition-all hover:-translate-y-1"
                          title="換一張圖"
                        >
                          <ArrowPathIcon className="w-6 h-6" />
                        </button>
                      </>
                    ) : (
                      <div className="flex flex-col items-center gap-2 text-slate-300 text-center px-4">
                        {currentGroup.imageError ? (
                            <>
                                <ExclamationCircleIcon className="w-16 h-16 text-red-300" />
                                <span className="font-bold text-red-400">{currentGroup.imageError}</span>
                                <button
                                    onClick={handleRegenerateImage}
                                    className="mt-2 text-sm font-bold text-white bg-red-300 hover:bg-red-400 px-4 py-1.5 rounded-full"
                                >
                                    再試一次
                                </button>
                            </>
                        ) : (
                            <>
                                <PhotoIcon className="w-16 h-16 opacity-30" />
                                <span className="font-bold">圖片準備中</span>
                            </>
                        )}
                      </div>
                    )}
                  </div>

                  {/* Info Section */}
                  <div className="flex-1 flex flex-col justify-center space-y-5 w-full overflow-hidden">
                     <div>
                       <div className="flex flex-wrap items-center gap-4 mb-2">
                          <h2 
                            className="font-black text-slate-800 tracking-tight transition-all duration-300 leading-none drop-shadow-sm"
                            style={{ fontSize: `${4.5 * viewScale}rem` }}
                          >
                            {currentGroup.text}
                          </h2>
                          <AudioButton 
                            text={currentGroup.text} 
                            className="flex-shrink-0"
                          />
                       </div>
                       <div className="inline-block bg-purple-100 text-purple-700 px-4 py-1.5 rounded-xl text-xl font-bold font-mono border-2 border-purple-200">
                         {currentGroup.jyutping}
                       </div>
                     </div>

                     <div className="bg-paper p-5 rounded-2xl border-2 border-yellow-200 text-slate-700 leading-relaxed shadow-[4px_4px_0_rgb(254,240,138)] relative">
                        <div className="absolute -top-3 -left-3 bg-yellow-400 rounded-full p-1.5 border-2 border-white shadow-sm">
                            <BookOpenIcon className="w-4 h-4 text-yellow-900" />
                        </div>
                        <p className="font-medium text-lg">{currentGroup.definition}</p>
                     </div>
                  </div>
                </div>
              </div>

              {/* Stroke Order Grid - Green Board Style */}
              <div className="bg-white rounded-[2.5rem] p-6 shadow-xl border-4 border-white ring-4 ring-green-100 overflow-hidden relative">
                <div className="absolute top-0 left-0 w-full h-4 bg-green-100"></div>

                <div className="flex items-center justify-between mb-6 pb-4 border-b-2 border-dashed border-slate-100 mt-2">
                   <h3 className="text-xl font-black text-slate-700 flex items-center gap-3">
                     <div className="bg-green-100 p-2 rounded-xl text-green-600">
                        <PencilSquareIcon className="w-6 h-6" />
                     </div>
                     筆順練習
                   </h3>
                   <div className="flex items-center gap-3">
                      <label className="flex items-center gap-2 cursor-pointer select-none bg-slate-50 px-3 py-1.5 rounded-full border border-slate-200 hover:border-slate-300 transition-colors">
                        <span className="text-sm font-bold text-slate-600">不停播放</span>
                        <div className="relative inline-flex items-center">
                          <input 
                            type="checkbox" 
                            className="sr-only peer" 
                            checked={isLooping}
                            onChange={(e) => setIsLooping(e.target.checked)}
                          />
                          <div className="w-10 h-6 bg-slate-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-crayon-green"></div>
                        </div>
                      </label>
                      <button
                        onClick={triggerAnimation}
                        className="p-2 text-white bg-crayon-blue hover:bg-sky-500 rounded-full shadow-md transition-all active:scale-90"
                        title="重播所有"
                      >
                        <ArrowPathIcon className="w-6 h-6" />
                      </button>
                   </div>
                </div>

                {/* Horizontal Scroll Container */}
                <div className="w-full overflow-x-auto pb-4 -mb-4 scrollbar-thin scrollbar-thumb-green-200 scrollbar-track-transparent">
                  <div className="flex gap-6 min-w-min px-2 py-2">
                    {currentGroup.characters.map((charData, idx) => (
                      <div key={`${currentGroup.id}-char-${idx}`} className="flex flex-col items-center flex-shrink-0 group">
                         <div className="transform transition-transform group-hover:-translate-y-2 duration-300">
                            <StrokeCharacter 
                                char={charData.char} 
                                size={140} 
                                animate={animateTrigger} 
                                loop={isLooping}
                              />
                         </div>
                         <div className="mt-3 text-2xl font-black text-slate-300 font-serif bg-slate-50 px-4 py-1 rounded-lg">
                           {charData.char}
                         </div>
                      </div>
                    ))}
                  </div>
                </div>

              </div>
            </div>

            {/* List Selection (Right Column) - Sticker Style */}
            <div className="lg:col-span-4">
               <div className="bg-white/80 backdrop-blur rounded-[2rem] shadow-sm border-2 border-white ring-2 ring-indigo-100 overflow-hidden sticky top-24">
                 <div className="p-5 bg-indigo-50/80 border-b border-indigo-100 flex items-center justify-between">
                    <h3 className="font-bold text-indigo-900 flex items-center gap-2">
                        <StarIcon className="w-5 h-5 text-indigo-500" />
                        詞語列表
                    </h3>
                    <div className="flex items-center gap-2">
                        <button
                          onClick={handleRandomSelect}
                          disabled={vocabGroups.length <= 1}
                          className="p-2 text-indigo-400 hover:text-white hover:bg-indigo-400 rounded-xl transition-colors disabled:opacity-30 disabled:cursor-not-allowed"
                          title="隨機抽一張"
                        >
                          <ArrowsRightLeftIcon className="w-5 h-5" />
                        </button>
                        <span className="text-xs font-bold bg-white text-indigo-600 px-3 py-1 rounded-full border border-indigo-100">
                          {vocabGroups.length}
                        </span>
                    </div>
                 </div>

                 <div className="p-3 max-h-[calc(100vh-200px)] overflow-y-auto space-y-3 scrollbar-thin scrollbar-thumb-indigo-200">
                    {vocabGroups.map((group, idx) => (
                      <button
                        key={group.id}
                        onClick={() => handleGroupSelect(idx)}
                        className={`w-full text-left p-4 rounded-2xl border-2 transition-all flex items-center gap-4 relative overflow-hidden group ${
                          selectedGroupIndex === idx
                            ? 'border-crayon-blue bg-white shadow-[0_4px_0_rgb(56,189,248)] translate-y-[-2px]'
                            : 'border-transparent hover:bg-white hover:border-indigo-100 hover:shadow-sm text-slate-500'
                        }`}
                      >
                        <div className={`
                            w-10 h-10 rounded-full flex items-center justify-center text-lg font-bold flex-shrink-0 transition-colors
                            ${selectedGroupIndex === idx ? 'bg-crayon-blue text-white' : 'bg-slate-100 text-slate-400 group-hover:bg-indigo-50 group-hover:text-indigo-400'}
                        `}>
                            {idx + 1}
                        </div>

                        <div className="flex-1">
                          <span className={`text-lg font-bold block ${
                            selectedGroupIndex === idx ? 'text-slate-800' : 'text-slate-600'
                          }`}>
                            {group.text}
                          </span>
                        </div>

                        {selectedGroupIndex === idx && (
                            <div className="absolute right-0 top-0 bottom-0 w-2 bg-crayon-blue"></div>
                        )}
                      </button>
                    ))}
                 </div>
               </div>
            </div>

          </div>
        )}

        {/* Empty State - Cute Version */}
        {!loading && vocabGroups.length === 0 && (
          <div className="text-center py-24 text-slate-400 bg-white/50 rounded-[3rem] border-4 border-dashed border-slate-200">
             <div className="inline-block p-6 bg-white rounded-full shadow-sm mb-4">
                 <FaceSmileIcon className="w-20 h-20 text-crayon-yellow" />
             </div>
             <h3 className="text-2xl font-bold text-slate-600 mb-2">準備好學習了嗎？</h3>
             <p className="text-lg opacity-60">請在上方輸入詞語，然後按「開始」！</p>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { analyzeVocabList, generateWordImage } from './services/geminiService';
import StrokeCharacter from './components/StrokeCharacter';
import AudioButton from './components/AudioButton';
import { VocabGroup } from './types';
import { 
  PencilSquareIcon, 
  SparklesIcon, 
  ArrowPathIcon,
  PhotoIcon,
  ClockIcon,
  XMarkIcon,
  ArrowsRightLeftIcon,
  MagnifyingGlassPlusIcon,
  MagnifyingGlassMinusIcon,
  ExclamationCircleIcon,
  StarIcon,
  BookOpenIcon,
  FaceSmileIcon
} from '@heroicons/react/24/outline';

const HISTORY_KEY = 'cantonese_app_history';

const App: React.FC = () => {
  const [inputText, setInputText] = useState<string>('你好、學校、圖書館');

  const [vocabGroups, setVocabGroups] = useState<VocabGroup[]>([]);
  const [loading, setLoading] = useState<boolean>(false);

  // Selection State
  const [selectedGroupIndex, setSelectedGroupIndex] = useState<number>(0);

  // Animation State
  const [animateTrigger, setAnimateTrigger] = useState<boolean>(false);
  const [isLooping, setIsLooping] = useState<boolean>(false);

  // View Settings
  const [viewScale, setViewScale] = useState<number>(1.0);

  // History State
  const [history, setHistory] = useState<string[]>([]);

  // Initialize History
  useEffect(() => {
    const saved = localStorage.getItem(HISTORY_KEY);
    if (saved) {
      try {
        setHistory(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse history", e);
      }
    }

    // Initial analysis
    performAnalysis('你好、學校、圖書館', false);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const addToHistory = (text: string) => {
    setHistory(prev => {
      // Remove if exists to move to top, limit to 20 items
      const filtered = prev.filter(item => item !== text);
      const newHistory = [text, ...filtered].slice(0, 20);
      localStorage.setItem(HISTORY_KEY, JSON.stringify(newHistory));
      return newHistory;
    });
  };

  const removeFromHistory = (e: React.MouseEvent, textToRemove: string) => {
    e.stopPropagation();
    setHistory(prev => {
      const newHistory = prev.filter(item => item !== textToRemove);
      localStorage.setItem(HISTORY_KEY, JSON.stringify(newHistory));
      return newHistory;
    });
  };

  const adjustScale = (delta: number) => {
    setViewScale(prev => {
      const newVal = prev + delta;
      return Math.min(Math.max(newVal, 0.4), 2.0); // Expanded range
    });
  };

  // Effect to load image for the selected group if it doesn't exist
  useEffect(() => {
    const loadCurrentGroupImage = async () => {
      if (vocabGroups.length === 0) return;
      const group = vocabGroups[selectedGroupIndex];

      if (!group || group.imageUrl || group.isImageLoading || group.imageError) return;

      // Update state to loading
      setVocabGroups(prev => {
        const newGroups = [...prev];
        newGroups[selectedGroupIndex] = { ...newGroups[selectedGroupIndex], isImageLoading: true };
        return newGroups;
      });

      // Fetch image
      const result = await generateWordImage(group.text);

      // Update state with image
      setVocabGroups(prev => {
        const newGroups = [...prev];
        newGroups[selectedGroupIndex] = { 
          ...newGroups[selectedGroupIndex], 
          imageUrl: result.imageUrl,
          imageError: result.error,
          isImageLoading: false
        };
        return newGroups;
      });
    };

    loadCurrentGroupImage();
  }, [selectedGroupIndex, vocabGroups.length]); 

  const performAnalysis = async (text: string, saveHistory: boolean = true) => {
    if (!text.trim()) return;

    setLoading(true);
    setVocabGroups([]); 
    setSelectedGroupIndex(0);

    try {
      // Split by dunhao or standard commas
      const words = text.split(/[、,，]/).map(s => s.trim()).filter(s => s.length > 0);

      const analyzedGroups = await analyzeVocabList(words);
      setVocabGroups(analyzedGroups);

      if (saveHistory && analyzedGroups.length > 0) {
        addToHistory(text);
      }

    } catch (error) {
      console.error("Failed to analyze", error);
    } finally {
      setLoading(false);
    }
  };

  const handleAnalyzeClick = () => {
    performAnalysis(inputText, true);
  };

  const handleHistoryClick = (text: string) => {
    setInputText(text);
    performAnalysis(text, true); // Move to top of history
  };

  const triggerAnimation = () => {
    setAnimateTrigger(false);
    setTimeout(() => setAnimateTrigger(true), 50);
  };

  const handleGroupSelect = (index: number) => {
    setSelectedGroupIndex(index);
    setAnimateTrigger(false);
    setTimeout(() => setAnimateTrigger(true), 100);
  };

  const handleRandomSelect = () => {
    if (vocabGroups.length <= 1) return;
    let nextIndex = selectedGroupIndex;
    // Ensure we pick a different word if possible
    while (nextIndex === selectedGroupIndex) {
      nextIndex = Math.floor(Math.random() * vocabGroups.length);
    }
    handleGroupSelect(nextIndex);
  };

  const handleRegenerateImage = async (e: React.MouseEvent) => {
    e.stopPropagation();
    const group = vocabGroups[selectedGroupIndex];
    if (!group) return;

    // Set loading state
    setVocabGroups(prev => {
      const newGroups = [...prev];
      newGroups[selectedGroupIndex] = { ...group, isImageLoading: true, imageUrl: undefined, imageError: undefined };
      return newGroups;
    });

    // Fetch new image
    const result = await generateWordImage(group.text);

    // Update state
    setVocabGroups(prev => {
      const newGroups = [...prev];
      newGroups[selectedGroupIndex] = { 
        ...group, 
        isImageLoading: false, 
        imageUrl: result.imageUrl,
        imageError: result.error
      };
      return newGroups;
    });
  };

  const currentGroup = vocabGroups[selectedGroupIndex];

  return (
    <div className="min-h-screen bg-sky-100/50 flex flex-col font-sans text-slate-800 pb-12">

      {/* Fun Header */}
      <header className="bg-crayon-yellow border-b-4 border-yellow-500 sticky top-0 z-30 shadow-sm">
        <div className="max-w-4xl mx-auto px-4 py-3 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-white rounded-2xl shadow-sm rotate-3 border-2 border-yellow-600">
              <PencilSquareIcon className="w-7 h-7 text-yellow-600" />
            </div>
            <h1 className="text-2xl font-black tracking-tight text-yellow-900 drop-shadow-sm">
              粵語生字筆順王
            </h1>
          </div>
          <div className="hidden sm:flex items-center gap-2 bg-white/30 px-3 py-1.5 rounded-full border-2 border-white/40 text-yellow-900 text-xs font-bold">
             <SparklesIcon className="w-4 h-4" />
             AI 智能助教
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-4xl w-full mx-auto px-4 py-6 space-y-6">

        {/* Input Mission Control */}
        <section className="bg-white rounded-[2rem] p-6 shadow-[0_8px_0_rgb(0,0,0,0.05)] border-4 border-white ring-4 ring-sky-200">
          <label htmlFor="vocabInput" className="block text-lg font-bold text-sky-800 mb-3 flex items-center gap-2">
            <FaceSmileIcon className="w-6 h-6 text-sky-500" />
            輸入詞語（請用頓號、分開）：
          </label>
          <div className="flex flex-col sm:flex-row gap-3">
            <input
              id="vocabInput"
              type="text"
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleAnalyzeClick()}
              placeholder="例如：學校、圖書館、超級市場..."
              className="flex-1 border-2 border-sky-200 rounded-2xl px-5 py-4 text-lg focus:border-sky-400 focus:ring-4 focus:ring-sky-100 outline-none transition-all placeholder:text-sky-300"
            />
            <button
              onClick={handleAnalyzeClick}
              disabled={loading || !inputText.trim()}
              className="bg-crayon-blue hover:bg-sky-400 disabled:bg-slate-300 text-white px-8 py-4 rounded-2xl font-bold text-lg shadow-[0_4px_0_rgb(14,165,233)] hover:shadow-[0_2px_0_rgb(14,165,233)] hover:translate-y-[2px] active:translate-y-[4px] active:shadow-none transition-all flex items-center justify-center gap-2 whitespace-nowrap min-w-[140px]"
            >
              {loading ? (
                <ArrowPathIcon className="w-6 h-6 animate-spin" />
              ) : (
                <SparklesIcon className="w-6 h-6" />
              )}
              <span>開始！</span>
            </button>
          </div>

          {/* History Chips */}
          {history.length > 0 && (
            <div className="mt-6 pt-4 border-t-2 border-dashed border-slate-100">
              <div className="flex items-center gap-2 mb-3">
                <ClockIcon className="w-5 h-5 text-slate-400" />
                <h3 className="text-sm font-bold text-slate-400 uppercase tracking-wider">剛才學過</h3>
              </div>
              <div className="flex flex-wrap gap-2">
                {history.map(item => (
                  <div 
                    key={item} 
                    onClick={() => handleHistoryClick(item)}
                    className="group relative flex items-center gap-2 px-4 py-2 bg-slate-50 hover:bg-yellow-50 border-2 border-slate-200 hover:border-yellow-300 rounded-full cursor-pointer transition-all text-slate-600 hover:text-yellow-800"
                  >
                    <span className="font-medium">{item}</span>
                    <button 
                      onClick={(e) => removeFromHistory(e, item)}
                      className="p-1 rounded-full hover:bg-red-100 text-slate-300 hover:text-red-500 opacity-50 group-hover:opacity-100 transition-all"
                      title="刪除紀錄"
                    >
                      <XMarkIcon className="w-4 h-4" />
                    </button>
                  </div>
                ))}
              </div>
            </div>
          )}
        </section>

        {/* COMPACT VOCAB LIST */}
        {vocabGroups.length > 0 && (
           <div className="bg-white/60 backdrop-blur-sm rounded-2xl p-3 border-2 border-indigo-100 shadow-sm overflow-hidden">
             <div className="flex items-center justify-between mb-2 px-1">
                <div className="flex items-center gap-2">
                   <div className="bg-indigo-100 p-1.5 rounded-lg">
                      <StarIcon className="w-4 h-4 text-indigo-600" />
                   </div>
                   <h3 className="font-bold text-indigo-900 text-sm">詞語列表</h3>
                   <span className="bg-indigo-100 text-indigo-600 text-xs font-bold px-2 py-0.5 rounded-full">
                      {vocabGroups.length}
                   </span>
                </div>

                <button
                  onClick={handleRandomSelect}
                  disabled={vocabGroups.length <= 1}
                  className="flex items-center gap-1 text-xs font-bold text-indigo-500 hover:text-indigo-700 bg-transparent hover:bg-indigo-100 px-2 py-1 rounded-lg transition-colors disabled:opacity-30"
                >
                   <ArrowsRightLeftIcon className="w-3 h-3" />
                   <span>隨機</span>
                </button>
             </div>

             <div className="flex gap-2 overflow-x-auto pb-2 pt-1 px-1 snap-x scrollbar-hide">
                {vocabGroups.map((group, idx) => (
                  <button
                    key={group.id}
                    onClick={() => handleGroupSelect(idx)}
                    className={`
                      snap-start flex-shrink-0 flex items-center gap-2 px-3 py-2 rounded-xl border-2 transition-all select-none
                      ${selectedGroupIndex === idx 
                        ? 'bg-white border-crayon-blue shadow-[0_3px_0_rgb(56,189,248)] -translate-y-[1px] text-slate-800' 
                        : 'bg-white/40 border-transparent hover:bg-white hover:border-indigo-100 text-slate-500 hover:shadow-sm'}
                    `}
                  >
                    <div className={`
                        w-6 h-6 rounded-full flex items-center justify-center text-xs font-bold flex-shrink-0 transition-colors
                        ${selectedGroupIndex === idx ? 'bg-crayon-blue text-white' : 'bg-slate-200 text-slate-400'}
                    `}>
                        {idx + 1}
                    </div>
                    <span className="font-bold whitespace-nowrap">{group.text}</span>
                  </button>
                ))}
             </div>
           </div>
        )}

        {vocabGroups.length > 0 && currentGroup && (
            <div className="flex flex-col gap-6">

              {/* Word Learning Card */}
              <div className="bg-white rounded-[2.5rem] p-6 sm:p-8 shadow-xl border-4 border-white ring-4 ring-purple-100 relative group/card overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-4 bg-purple-100"></div>

                {/* Zoom Controls */}
                <div className="absolute top-6 right-6 flex items-center gap-2 z-10">
                   <div className="flex bg-white/80 backdrop-blur border-2 border-slate-100 rounded-xl p-1 shadow-sm">
                      <button 
                        onClick={() => adjustScale(-0.1)}
                        className="p-1.5 text-slate-400 hover:bg-slate-100 rounded-lg hover:text-sky-500 transition-colors"
                        title="縮小"
                      >
                        <MagnifyingGlassMinusIcon className="w-5 h-5" />
                      </button>
                      <button 
                        onClick={() => adjustScale(0.1)}
                        className="p-1.5 text-slate-400 hover:bg-slate-100 rounded-lg hover:text-sky-500 transition-colors"
                        title="放大"
                      >
                        <MagnifyingGlassPlusIcon className="w-5 h-5" />
                      </button>
                   </div>
                </div>

                <div className="flex flex-col md:flex-row gap-8 mt-6 items-center md:items-start relative z-0">
                  {/* Image Section - Picture Frame Style */}
                  <div 
                    className="w-full aspect-square bg-slate-50 rounded-3xl flex items-center justify-center overflow-hidden border-4 border-slate-100 shadow-inner relative group flex-shrink-0 transition-all duration-300"
                    style={{ flexBasis: `${40 * viewScale}%`, maxWidth: '100%' }}
                  >
                    {currentGroup.isImageLoading ? (
                       <div className="flex flex-col items-center gap-3 text-crayon-blue">
                         <div className="relative">
                            <PhotoIcon className="w-16 h-16 animate-bounce opacity-50" />
                            <SparklesIcon className="w-8 h-8 absolute -top-2 -right-2 text-yellow-400 animate-spin" />
                         </div>
                         <span className="font-bold text-sm tracking-wide bg-sky-50 px-3 py-1 rounded-full">畫圖中...</span>
                       </div>
                    ) : currentGroup.imageUrl ? (
                      <>
                        <img 
                          src={currentGroup.imageUrl} 
                          alt={currentGroup.text} 
                          className="w-full h-full object-contain p-4 transition-transform duration-700 hover:scale-110" 
                        />
                        {/* Regenerate Button Overlay */}
                        <button
                          onClick={handleRegenerateImage}
                          className="absolute bottom-4 right-4 bg-white hover:bg-sky-50 text-slate-400 hover:text-sky-600 p-3 rounded-2xl shadow-lg border-2 border-slate-100 transition-all hover:-translate-y-1"
                          title="換一張圖"
                        >
                          <ArrowPathIcon className="w-6 h-6" />
                        </button>
                      </>
                    ) : (
