                      ${selectedGroupIndex === idx 
                        ? 'bg-white border-crayon-blue shadow-[0_3px_0_rgb(56,189,248)] -translate-y-[1px] text-slate-800' 
                        : 'bg-white/40 border-transparent hover:bg-white hover:border-indigo-100 text-slate-500 hover:shadow-sm'}
                    `}
                  >
                    <div className={`
                        w-6 h-6 rounded-full flex items-center justify-center text-xs font-bold flex-shrink-0 transition-colors
